const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json;charset=UTF-8','access-control-allow-origin':'*','access-control-allow-headers':'Content-Type, Authorization'}});
const body=async req=>{try{return await req.json()}catch{return {}}};
const token=req=>String(req.headers.get('authorization')||'').replace(/^Bearer\s+/i,'');
const productOut=p=>{if(!p)return p;let images=[],sizes=[];try{images=JSON.parse(p.images||'[]')}catch{images=p.images?[String(p.images)]:[]}try{sizes=JSON.parse(p.sizes||'[]')}catch{sizes=[]}return {...p,salePrice:p.sale_price,imageUrl:p.image_url,images,sizes,createdAt:p.created_at}};
async function admin(req,env){const t=token(req);if(!t||t!==env.ADMIN_TOKEN)return json({message:'Admin login required'},401);return null}
export default {async fetch(req,env){const url=new URL(req.url);if(req.method==='OPTIONS')return new Response(null,{headers:{'access-control-allow-origin':'*','access-control-allow-methods':'GET,POST,PATCH,DELETE,OPTIONS','access-control-allow-headers':'Content-Type, Authorization'}});if(!url.pathname.startsWith('/api/'))return env.ASSETS.fetch(req);if(!env.DB)return json({message:'D1 database is not configured'},503);
try{if(url.pathname==='/api/health')return json({ok:true,service:'GiftWALA API'});
if(url.pathname==='/api/admin/login'&&req.method==='POST'){const b=await body(req);if(String(b.email)!==String(env.ADMIN_EMAIL)||String(b.password)!==String(env.ADMIN_PASSWORD))return json({message:'Invalid admin credentials'},401);return json({token:env.ADMIN_TOKEN,email:env.ADMIN_EMAIL})}
const singleProduct=url.pathname.match(/^\/api\/products\/([^/]+)$/);if(singleProduct&&req.method==='GET'){const key=decodeURIComponent(singleProduct[1]);const p=await env.DB.prepare('SELECT * FROM products WHERE id=? OR sku=? LIMIT 1').bind(key,key).first();return p?json(productOut(p)):json({message:'Product not found'},404)}
if(url.pathname==='/api/products'&&req.method==='GET'){const q=url.searchParams.get('category');const r=await env.DB.prepare(`SELECT * FROM products ${q?'WHERE category=?':''} ORDER BY featured DESC, created_at DESC`).bind(...(q?[q]:[])).all();return json(r.results.map(productOut))}
if(url.pathname==='/api/categories'&&req.method==='GET'){const r=await env.DB.prepare('SELECT name FROM categories UNION SELECT DISTINCT category AS name FROM products ORDER BY name').all();return json(r.results.map(x=>x.name))}
if(url.pathname==='/api/builder-settings'&&req.method==='GET'){const r=await env.DB.prepare('SELECT key,value FROM builder_settings').all();return json(Object.fromEntries(r.results.map(x=>[x.key,x.value])))}
if(url.pathname==='/api/orders'&&req.method==='POST'){const b=await body(req);if(!b.customer?.name||!b.customer?.phone||!b.customer?.address||!b.items?.length)return json({message:'Customer and order details are required'},400);const id=crypto.randomUUID(),total=b.items.reduce((s,x)=>s+Number(x.price||0)*Number(x.quantity||1),0);await env.DB.prepare('INSERT INTO orders (id,customer_name,phone,email,address,payment_method,items,total,status,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)').bind(id,b.customer.name,b.customer.phone,b.customer.email||'',b.customer.address,b.paymentMethod||'Cash on Delivery',JSON.stringify(b.items),total,'pending',Date.now()).run();return json({_id:id,total,status:'pending'},201)}
const guard=await admin(req,env);if(guard)return guard;
if(url.pathname==='/api/uploads/image'&&req.method==='POST'){const b=await body(req),data=String(b.data||'');if(!/^data:image\/(png|jpeg|jpg|webp);base64,/i.test(data))return json({message:'Send a PNG, JPG or WEBP image'},400);if(data.length>7*1024*1024)return json({message:'Image must be 5MB or smaller'},413);return json({url:data,filename:String(b.filename||'image')},201)}
if(url.pathname==='/api/admin/builder-settings'&&req.method==='PATCH'){const b=await body(req);for(const [key,value] of Object.entries(b)){await env.DB.prepare('INSERT INTO builder_settings (key,value) VALUES (?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value').bind(key,String(value??'')).run()}return json({ok:true})}
if(url.pathname==='/api/products'&&req.method==='POST'){const b=await body(req);const id=crypto.randomUUID();await env.DB.prepare('INSERT INTO products (id,name,sku,category,price,sale_price,stock,description,image_url,images,featured,created_at,sizes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id,b.name,b.sku,b.category,Number(b.price||0),Number(b.salePrice||b.price||0),Number(b.stock||0),b.description||'',b.imageUrl||'',JSON.stringify(b.images||[]),0,Date.now(),JSON.stringify(Array.isArray(b.sizes)?b.sizes:[])).run();return json({...b,_id:id},201)}
if(url.pathname==='/api/categories'&&req.method==='POST'){const b=await body(req);const name=String(b.name||'').trim();if(!name)return json({message:'Category name required'},400);try{const id=crypto.randomUUID();await env.DB.prepare('INSERT INTO categories (id,name,created_at) VALUES (?,?,?)').bind(id,name,Date.now()).run();return json({id,name},201)}catch(e){return json({message:'Category already exists'},409)}}
const cb=url.pathname.match(/^\/api\/categories\/by-name\/(.+)$/);if(cb&&req.method==='PATCH'){const b=await body(req);const old=decodeURIComponent(cb[1]),name=String(b.name||'').trim();if(!name)return json({message:'Category name required'},400);try{const result=await env.DB.prepare('UPDATE categories SET name=? WHERE name=?').bind(name,old).run();if(!result.meta?.changes)return json({message:'Category not found'},404);await env.DB.prepare('UPDATE products SET category=? WHERE category=?').bind(name,old).run();return json({name})}catch(e){return json({message:'Category already exists'},409)}}
const pm=url.pathname.match(/^\/api\/products\/([^/]+)$/);if(pm&&req.method==='PATCH'){const b=await body(req);await env.DB.prepare('UPDATE products SET name=?,sku=?,category=?,price=?,sale_price=?,stock=?,description=?,featured=?,images=?,image_url=?,sizes=? WHERE id=? OR sku=?').bind(b.name,b.sku,b.category,Number(b.price||0),Number(b.salePrice||b.price||0),Number(b.stock||0),b.description||'',b.featured?1:0,JSON.stringify(b.images||[]),(b.images||[])[0]||b.imageUrl||'',JSON.stringify(Array.isArray(b.sizes)?b.sizes:[]),pm[1],pm[1]).run();return json({ok:true})}
if(url.pathname==='/api/orders'&&req.method==='GET'){const r=await env.DB.prepare('SELECT * FROM orders ORDER BY created_at DESC LIMIT 200').all();return json(r.results)}
const om=url.pathname.match(/^\/api\/orders\/([^/]+)\/status$/);if(om&&req.method==='PATCH'){const b=await body(req);await env.DB.prepare('UPDATE orders SET status=? WHERE id=?').bind(b.status,om[1]).run();return json({ok:true})}
if(url.pathname==='/api/admin/stats'){const p=await env.DB.prepare('SELECT COUNT(*) count FROM products').first();const o=await env.DB.prepare('SELECT COUNT(*) count, COALESCE(SUM(total),0) sales FROM orders WHERE status!=?').bind('cancelled').first();return json({products:p.count,orders:o.count,sales:o.sales,customers:0})}
return json({message:'API route not found'},404)}catch(e){return json({message:e.message||'Server error'},500)}}};
